import re
from binascii import unhexlify

def get_blocks(hex_cookie, block_size=16):
    raw = unhexlify(hex_cookie)
    return [raw[i:i+block_size] for i in range(0, len(raw), block_size)]

def analyze(filename):
    pattern = re.compile(r"Username: '(.*?)' \(len=(\d+)\).*?Your Cookie is: ([0-9a-fA-F]+)", re.DOTALL)
    with open(filename, 'r') as f:
        data = f.read()

    findings = []
    for m in pattern.finditer(data):
        username = m.group(1)
        ulen = int(m.group(2))
        hex_cookie = m.group(3)
        blocks = get_blocks(hex_cookie)
        seen = {}
        repeats = []
        for i, b in enumerate(blocks):
            if b in seen:
                repeats.append((seen[b], i, b))
            else:
                seen[b] = i
        findings.append({'username': username, 'len': ulen, 'hex_cookie': hex_cookie, 'blocks': blocks, 'repeats': repeats})
    return findings

def find_first_repeat(findings):
    for f in sorted(findings, key=lambda x: x['len']):
        if f['repeats']:
            return f
    return None

def illustrate(f, block_size=16):
    s = f"Username: '{f['username']}' (len={f['len']})\nHex Cookie: {f['hex_cookie']}\n"
    s += f"Block breakdown (block size = {block_size} bytes):\n"
    for i, b in enumerate(f['blocks']):
        marker = ''
        for (j, k, repblock) in f['repeats']:
            if i == j:
                marker += ' [repeat start]'
            if i == k:
                marker += ' [repeat end]'
        s += f"  Block {i:02d}: {b.hex()}{marker}\n"
    s += "Repetition offsets: " + ", ".join([f"blocks {j} and {k} ({repblock.hex()})" for (j, k, repblock) in f['repeats']]) + '\n'
    return s

def summarize_all(findings, block_size=16):
    report = []
    report.append("Block repetition analysis of edgecase_usernames_results.txt\n")
    report.append(f"Block size assumed: {block_size} bytes\n")
    for f in findings:
        if f['repeats']:
            report.append(illustrate(f, block_size))
    first = find_first_repeat(findings)
    if first:
        report.append("\nSUMMARY: Minimum username length triggering block repetition: {} ('{}').".format(first['len'], first['username']))
        report.append("This is strong evidence of ECB mode encryption and potential cut-and-paste attacks.\n")
    else:
        report.append("No block repetitions found in output. ECB is unlikely.")
    return '\n'.join(report)

def main():
    findings = analyze('/home/ctfplayer/ctf_files/edgecase_usernames_results.txt')
    report = summarize_all(findings)
    with open('/home/ctfplayer/ctf_files/block_pattern_report.txt', 'w') as out:
        out.write(report)

if __name__ == '__main__':
    main()

from pwn import remote
import binascii

HOST = 'crypto.chal.csaw.io'
PORT = 8000

BLOCK_SIZE = 16
ALPHABET = '0123456789abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ'

def chunk_blocks(data, blen):
    return [data[i:i+blen] for i in range(0, len(data), blen)]

def interact_and_grab_cookie(username):
    conn = remote(HOST, PORT)
    try:
        # Don't wait for 'username:' prompt, send right away
        conn.sendline(username.encode())
        output = conn.recvall(timeout=5).decode(errors='replace')
    except Exception as e:
        output = f'[EXCEPTION] {e}'
    finally:
        conn.close()
    return output

def extract_cookie(line):
    # Find something that looks like a hex or b64 session cookie
    import re
    base64pat = r"([A-Za-z0-9+/=]{16,})"
    hexpat = r"([A-Fa-f0-9]{16,})"
    result = re.findall(base64pat, line)
    if result:
        try:
            import base64
            base64test = base64.b64decode(result[0], validate=True)
        except Exception:
            base64test = None
        if base64test:
            return result[0], 'base64'
    result = re.findall(hexpat, line)
    if result:
        try:
            bytes.fromhex(result[0])
            return result[0], 'hex'
        except Exception:
            pass
    return None, None

def decode_cookie(cookie, mode):
    if mode == 'base64':
        import base64
        return base64.b64decode(cookie)
    else:
        return bytes.fromhex(cookie)

def gen_report(text):
    with open("/home/ctfplayer/ctf_files/final_structural_ecb_attack.txt", "a") as f:
        f.write(text + '\n')

report_section = ""
all_cookies = {}
admin_blocks = []

report_section += f"Trying usernames of form: 'A'*n + 'admin' for n in 11..27\n"

for n in range(11, 28):
    uname = 'A' * n + 'admin'
    resp = interact_and_grab_cookie(uname)
    report_section += f"[ORIGINAL] Username: '{uname}' Response: {resp.strip()}\n"
    cookie, mode = extract_cookie(resp)
    if not cookie:
        report_section += f"  [!] No cookie found for username={uname}\n"
        continue
    cbytes = decode_cookie(cookie, mode)
    blist = chunk_blocks(cbytes, BLOCK_SIZE)
    all_cookies[uname] = {'cookie': cookie, 'mode': mode, 'raw': cbytes, 'blocks': blist}
    blocks_hex = ['[' + b.hex() + ']' for b in blist]
    admin_block_index = None
    for i, b in enumerate(blist):
        if b.find(b'admin') != -1:
            admin_block_index = i
            break
    report_section += (f"  Cookie blocks: {blocks_hex}\n")
    if admin_block_index is not None:
        admin_blocks.append((uname, admin_block_index, blist[admin_block_index]))
        report_section += (f"  [*] Block {admin_block_index} appears to contain 'admin' (offset {b''.join(blist).find(b'admin')})\n")
    else:
        report_section += (f"  [ ] No block found with explicit 'admin'\n")
    report_section += '\n'

plain_unames = ['A'*i for i in range(16, 24)]
for uname in plain_unames:
    resp = interact_and_grab_cookie(uname)
    report_section += f"[ORIGINAL] Username: '{uname}' Response: {resp.strip()}\n"
    cookie, mode = extract_cookie(resp)
    if not cookie:
        report_section += f"  [!] No cookie found for username={uname}\n"
        continue
    cbytes = decode_cookie(cookie, mode)
    blist = chunk_blocks(cbytes, BLOCK_SIZE)
    all_cookies[uname] = {'cookie': cookie, 'mode': mode, 'raw': cbytes, 'blocks': blist}
    blocks_hex = ['[' + b.hex() + ']' for b in blist]
    report_section += (f"  Cookie blocks: {blocks_hex}\n")
    report_section += '\n'

for (uname_admin, block_idx, admin_block) in admin_blocks:
    for plain_uname in plain_unames:
        orig_ck = all_cookies.get(plain_uname)
        if not orig_ck:
            continue
        orig_blocks = orig_ck['blocks']
        for swap_pos in [0, 1]:
            if len(orig_blocks) > swap_pos:
                forged_blocks = orig_blocks.copy()
                forged_blocks[swap_pos] = admin_block
                forged_cookie_bytes = b''.join(forged_blocks)
                if orig_ck['mode'] == 'base64':
                    import base64
                    forged_cookie = base64.b64encode(forged_cookie_bytes).decode()
                else:
                    forged_cookie = forged_cookie_bytes.hex()
                report_section += (f"[FORGED] Replacing block {swap_pos} in username '{plain_uname}' with 'admin' block from '{uname_admin}' at block {block_idx}\n")
                report_section += (f"  Forged cookie ({orig_ck['mode']}): {forged_cookie}\n")
                resp = interact_and_grab_cookie(forged_cookie)
                report_section += (f"  Forged cookie response for username='{forged_cookie}': {resp.strip()}\n")
                if 'flag{' in resp:
                    report_section += ('\n\n[!!!] FLAG FOUND: ' + resp + '\n\n')

report_section += '\nAttack complete. Observed all block arrangements and attempted all forgeries.\n'
gen_report(report_section)

